  const [salt, expected] = hash.split(":");
  if (!salt || !expected) return false;
  const actual = scryptSync(password, salt, 32);
  const exp = Buffer.from(expected, "hex");
  return exp.length === actual.length && timingSafeEqual(actual, exp);
}

